    // Audit �1: every active InterpreterFrame is registered here so the GC
    // sees its register/this/newtarget/env references as roots. Without this,
    // a cell only reachable through a frame register can be reclaimed by an
    // auto-MinorCollect inside user code and surface as "Stale heap handle.".
    private readonly Stack<InterpreterFrame> _activeFrames = new();
    // Browsers render an array that recursively contains itself as an empty
    // element while Array.prototype.join/toString is already processing that
    // same array. Without this guard, circular page data recurses indefinitely.
    private readonly HashSet<ObjectHandle> _activeArrayJoins = new();

    private readonly struct ActiveFrameScope : IDisposable
    {
        private readonly Stack<InterpreterFrame> _stack;
        public ActiveFrameScope(Stack<InterpreterFrame> stack, InterpreterFrame frame)
        {
            _stack = stack;
            stack.Push(frame);
        }
        public void Dispose() => _stack.Pop();
    }

    // All cached ObjectHandle fields of the interpreter (lazily-built builtin
    // prototypes, constructors, intrinsic functions). These caches must be GC
    // roots for the lifetime of the interpreter, but they were pinned with
    // heap.PushRoot — and the root set is a *stack*: any scoped pin window
    // (PushRoot … PopRootsTo) active while a lazy Ensure* ran would pop the
    // "permanent" root with its own, leaving the cached handle dangling. The
    // next minor GC then swept the still-cached prototype and every object
    // created from the cache afterwards had a stale [[Prototype]]. Tracing the
    // fields directly removes any dependence on PushRoot ordering.
    private static readonly System.Reflection.FieldInfo[] CachedHandleFields = BuildCachedHandleFieldTable();

    private static System.Reflection.FieldInfo[] BuildCachedHandleFieldTable()
    {
        return typeof(BytecodeInterpreter)
            .GetFields(System.Reflection.BindingFlags.Instance |
                       System.Reflection.BindingFlags.NonPublic |
                       System.Reflection.BindingFlags.Public)
            .Where(f => f.FieldType == typeof(ObjectHandle) || f.FieldType == typeof(ObjectHandle?))
            .ToArray();
    }

    void IHeapRootSource.TraceRoots(IHeapTracer tracer)
    {
        foreach (var frame in _activeFrames)
        {
            for (var i = 0; i < frame.Registers.Length; i++)
            {
                var v = frame.Registers[i];
                if (v.Tag == JsValueTag.Object) tracer.Trace(v.AsObjectHandle());
            }
            if (frame.ThisValue.Tag == JsValueTag.Object) tracer.Trace(frame.ThisValue.AsObjectHandle());
            if (frame.NewTarget.Tag == JsValueTag.Object) tracer.Trace(frame.NewTarget.AsObjectHandle());
            if (frame.PendingException is { } pe && pe.Tag == JsValueTag.Object)
                tracer.Trace(pe.AsObjectHandle());
            if (frame.PendingReturn is { } pr && pr.Tag == JsValueTag.Object)
                tracer.Trace(pr.AsObjectHandle());
            frame.Environment?.Trace(tracer);
        }

        foreach (var field in CachedHandleFields)
        {
            var raw = field.GetValue(this);
            if (raw is ObjectHandle handle)
            {
                tracer.Trace(handle);
            }
        }

        foreach (var propertySet in _hostDefinedProperties.Values)
        {
            foreach (var descriptor in propertySet.Values)
            {
                TraceRootValue(tracer, descriptor.Value);
                TraceRootValue(tracer, descriptor.Get);
                TraceRootValue(tracer, descriptor.Set);
            }
        }

        foreach (var prototype in _hostObjectPrototypes.Values)
        {
            TraceRootValue(tracer, prototype);
        }
    }

    private static void TraceRootValue(IHeapTracer tracer, JsValue value)
    {
        if (value.Tag == JsValueTag.Object)
        {
            tracer.Trace(value.AsObjectHandle());
        }
    }
