                    try { frame.Registers[ins.A] = BigIntArith(frame.Registers[ins.B], frame.Registers[ins.C], "division", (a, b) => a / b, (a, b) => a / b); }
                    catch (JsThrownException ex) { ThrowOrHandle(frame, ex.Value); }
