                    try { frame.Registers[ins.A] = JsValue.FromBoolean(AreEqual(frame.Registers[ins.B], frame.Registers[ins.C])); }
                    catch (JsThrownException ex) { ThrowOrHandle(frame, ex.Value); }
                    break;
                case OpCode.Neq:
                    try { frame.Registers[ins.A] = JsValue.FromBoolean(!AreEqual(frame.Registers[ins.B], frame.Registers[ins.C])); }
                    catch (JsThrownException ex) { ThrowOrHandle(frame, ex.Value); }
