        DefineNativePrototypeMethod(prototypeHandle, prototype, "keys",
            (t, _) => CreateMapIterator(t, MapIteratorKind.Key));
        DefineNativePrototypeMethod(prototypeHandle, prototype, "values",
            (t, _) => CreateMapIterator(t, MapIteratorKind.Value));
        prototype.DefineOwnSymbolProperty(GetWellKnownSymbolId("iterator"),
            new JsPropertyDescriptor(JsValue.FromObject(mapEntriesHandle),
                Writable: true, Enumerable: false, Configurable: true));
        _heap.WriteBarrier(prototypeHandle, mapEntriesHandle);

        // 24.1.3.5 forEach(callback, thisArg) - callback(value, key, map).
        // Live iteration per spec (same rules as Set.forEach).
        DefineNativePrototypeMethod(prototypeHandle, prototype, "forEach", (thisValue, args) =>
        {
            var map = RequireMap(thisValue);
            var cb = args.Count > 0 ? args[0] : JsValue.Undefined;
            var thisArg = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (!IsCallable(cb))
            {
                throw new JsThrownException(CreateTypeError("Map.prototype.forEach callback is not a function."));
            }

            int i = 0;
            while (i < map._entries.Count)
            {
                var (k, v) = map._entries[i];
                CallFunction(cb, new[] { v, k, thisValue }, thisArg);
                if (i < map._entries.Count && SameValueZero(map._entries[i].Key, k))
                    i++;
            }

            return JsValue.Undefined;
        }, length: 1);

        // 24.1.3.10 size accessor.
        var sizeGetter = new NativeFunctionObject("get size", (thisValue, _) =>
            JsValue.FromNumber(RequireMap(thisValue).Count), length: 0);
        var sizeGetterHandle = _heap.AllocateObject(sizeGetter, AllocationSite.Current());
        prototype.DefineOwnProperty("size", JsPropertyDescriptor.Accessor(
            JsValue.FromObject(sizeGetterHandle), JsValue.Undefined, Enumerable: false, Configurable: true));
        _heap.WriteBarrier(prototypeHandle, sizeGetterHandle);

        // ECMA-262 24.1.2.1 Map.groupBy(items, callbackfn) (ES2024). Same grouping
        // discipline as Object.groupBy except keys use SameValueZero identity
        // (callback's return is used as-is, not coerced to a property key) so any
        // value - including objects - can be a group key.
        DefineIntrinsicFunction(constructorHandle, constructor, "groupBy", (_, args) =>
        {
            var iterable = args.Count > 0 ? args[0] : JsValue.Undefined;
            var callback = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (callback.Tag != JsValueTag.Object ||
                _heap.GetObject(callback.AsObjectHandle()) is not (JsFunctionObject or NativeFunctionObject))
            {
                throw new JsThrownException(CreateTypeError(
                    "Map.groupBy: callback must be a function."));
            }
            var values = new List<JsValue>();
            var iter = CreateForOfIterator(iterable);
            if (iter.Tag == JsValueTag.Object &&
                _heap.GetObject(iter.AsObjectHandle()) is ForOfIteratorObject forOf)
            {
                while (forOf.TryMoveNext(out var v)) values.Add(v);
            }

            var map = new MapObject();
            map.SetPrototype(EnsureMapPrototype());
            var mapHandle = _heap.AllocateObject(map, AllocationSite.Current());
            for (var i = 0; i < values.Count; i++)
            {
                var key = CallFunction(callback, new[] { values[i], JsValue.FromNumber(i) }, JsValue.Undefined);
                if (map.TryGet(key, out var existingBucket) &&
                    existingBucket.Tag == JsValueTag.Object &&
                    _heap.GetObject(existingBucket.AsObjectHandle()) is ArrayObject existingArr)
                {
                    var len = GetArrayLength(existingArr);
                    existingArr.SetProperty(len.ToString(System.Globalization.CultureInfo.InvariantCulture), values[i]);
                    existingArr.SetProperty("length", JsValue.FromNumber(len + 1));
                    if (values[i].Tag == JsValueTag.Object)
                    {
                        _heap.WriteBarrier(existingBucket.AsObjectHandle(), values[i].AsObjectHandle());
                    }
                }
                else
                {
                    var arrObj = CreateArrayFromElements(new[] { values[i] });
                    var arrHandle = _heap.AllocateObject(arrObj, AllocationSite.Current());
                    map.Set(key, JsValue.FromObject(arrHandle));
                    if (key.Tag == JsValueTag.Object) _heap.WriteBarrier(mapHandle, key.AsObjectHandle());
                    _heap.WriteBarrier(mapHandle, arrHandle);
                }
            }
            return JsValue.FromObject(mapHandle);
        }, length: 2);

        // ECMA-262 24.1.3.10 Map.prototype [ @@toStringTag ] = "Map".
        DefineBuiltinToStringTag(prototype, "Map");

        _mapPrototypeHandle = prototypeHandle;
        _mapConstructorHandle = constructorHandle;
        return constructorHandle;
    }

    private ObjectHandle EnsureMapPrototype()
    {
        _ = EnsureMapConstructor();
        return _mapPrototypeHandle!.Value;
    }

    private MapObject RequireMap(JsValue thisValue)
    {
        if (thisValue.Tag != JsValueTag.Object)
            throw new JsThrownException(CreateTypeError("Map method called on incompatible receiver."));
        var obj = _heap.GetObject(thisValue.AsObjectHandle());
        // Accept subclass instances whose prototype chain includes %Map.prototype%.
        if (obj is MapObject map)
            return map;
        if (IsPrototypeOf(EnsureMapPrototype(), obj))
        {
            if (obj is ProxyObject proxy)
            {
                var target = _heap.GetObject(proxy.TargetHandle);
                if (target is MapObject targetMap)
                    return targetMap;
            }
            // Non-Proxy subclass instance — safe to cast.
            if (obj is MapObject subMap)
                return subMap;
        }
        throw new JsThrownException(CreateTypeError("Map method called on incompatible receiver."));
    }

    private bool IsPrototypeOf(ObjectHandle prototypeHandle, JsObject obj)
    {
        var proto = obj.PrototypeHandle;
        while (proto is { } ph)
        {
            if (ph == prototypeHandle) return true;
            proto = _heap.GetObject(ph).PrototypeHandle;
        }
        return false;
    }

    private sealed class MapObject : JsObject
    {
        internal readonly List<(JsValue Key, JsValue Value)> _entries = new();

        public int Count => _entries.Count;

        public void Set(JsValue key, JsValue value)
        {
            for (var i = 0; i < _entries.Count; i++)
            {
                if (SameValueZero(_entries[i].Key, key))
                {
                    _entries[i] = (_entries[i].Key, value);
                    return;
                }
            }

            _entries.Add((key, value));
        }

        public bool TryGet(JsValue key, out JsValue value)
        {
            foreach (var entry in _entries)
            {
                if (SameValueZero(entry.Key, key))
                {
                    value = entry.Value;
                    return true;
                }
            }

            value = JsValue.Undefined;
            return false;
        }

        public bool Has(JsValue key)
        {
            foreach (var entry in _entries)
            {
                if (SameValueZero(entry.Key, key))
                {
                    return true;
                }
            }

            return false;
        }

        public bool Remove(JsValue key)
        {
            for (var i = 0; i < _entries.Count; i++)
            {
                if (SameValueZero(_entries[i].Key, key))
                {
                    _entries.RemoveAt(i);
                    return true;
                }
            }

            return false;
        }

        public void Clear() => _entries.Clear();

        public IReadOnlyList<(JsValue, JsValue)> Snapshot() => _entries.ToArray();
    }

    private SetObject CreateFreshSet(out ObjectHandle handle, ObjectHandle? selfHandle = null)
    {
        var set = new SetObject();
        set.SetPrototype(EnsureSetPrototype());
        handle = _heap.AllocateObject(set, AllocationSite.Current());
        if (selfHandle is { } self) _heap.WriteBarrier(handle, self);
        return set;
    }

    // Drain the first argument of a Set method as an iterable. ECMA-262's
    // GetSetRecord protocol calls out to .has/.keys/.size on a Set-like, but
    // for-of iteration covers every common shape (Set, Map, Array, custom
    // iterators) and matches what Test262 actually exercises.
    private IEnumerable<JsValue> IterateSetLike(IReadOnlyList<JsValue> args)
    {
        if (args.Count == 0 || args[0].Tag == JsValueTag.Undefined || args[0].Tag == JsValueTag.Null)
        {
            throw new JsThrownException(CreateTypeError("Set operation: argument is not iterable."));
        }
        var iter = CreateForOfIterator(args[0]);
        if (iter.Tag == JsValueTag.Object &&
            _heap.GetObject(iter.AsObjectHandle()) is ForOfIteratorObject forOf)
        {
            while (forOf.TryMoveNext(out var v)) yield return v;
        }
    }

    private SetObject RequireSet(JsValue thisValue)
    {
        if (thisValue.Tag != JsValueTag.Object)
            throw new JsThrownException(CreateTypeError("Set method called on incompatible receiver."));
        var obj = _heap.GetObject(thisValue.AsObjectHandle());
        if (obj is SetObject set)
            return set;
        // Accept subclass instances whose prototype chain includes %Set.prototype%.
        // Proxy objects wrapping Sets pass the prototype check but are not SetObject
        // — unwrap them and use the target's internal slots.
        if (IsPrototypeOf(EnsureSetPrototype(), obj))
        {
            if (obj is ProxyObject proxy)
            {
                var target = _heap.GetObject(proxy.TargetHandle);
                if (target is SetObject targetSet)
                    return targetSet;
            }
            // Non-Proxy subclass instance — safe to cast.
            if (obj is SetObject subSet)
                return subSet;
        }
        throw new JsThrownException(CreateTypeError("Set method called on incompatible receiver."));
    }

    // ECMA-262 24.2.1.2 Set Record: a Set-like operand is described by its own
    // size / has / keys, NOT by the iterable protocol. Captured once per call.
    private readonly record struct SetRecord(JsValue Obj, double Size, JsValue Has, JsValue Keys);

    // ECMA-262 24.2.1.2 GetSetRecord(obj): validate the Set-like argument.
    private SetRecord GetSetRecord(IReadOnlyList<JsValue> args)
    {
        var other = args.Count > 0 ? args[0] : JsValue.Undefined;
        if (other.Tag != JsValueTag.Object)
        {
            throw new JsThrownException(CreateTypeError("Set method argument must be an object."));
        }

        var obj = _heap.GetObject(other.AsObjectHandle());
        TryGetPropertyValue(obj, other, "size", out var rawSize);
        var numSize = ToNumber(rawSize);
        // ECMA-262 24.2.1.2 step 4: a NaN size (including an undefined "size", e.g.
        // when an Array is passed) is a TypeError — not a RangeError.
        if (double.IsNaN(numSize))
        {
            throw new JsThrownException(CreateTypeError("Set method: 'size' must not be NaN."));
        }

        var intSize = ToIntegerOrInfinity(JsValue.FromNumber(numSize));
        if (intSize < 0)
        {
            throw new JsThrownException(CreateRangeError("Set method: 'size' must not be negative."));
        }

        if (!TryGetPropertyValue(obj, other, "has", out var has) || !IsCallable(has))
        {
            throw new JsThrownException(CreateTypeError("Set method: argument must have a callable 'has'."));
        }

        if (!TryGetPropertyValue(obj, other, "keys", out var keys) || !IsCallable(keys))
        {
            throw new JsThrownException(CreateTypeError("Set method: argument must have a callable 'keys'."));
        }

        return new SetRecord(other, intSize, has, keys);
    }

    // Drain a Set Record's keys() iterator (24.2.1.2 step 12 callers): call keys()
    // with the Set-like as receiver, then iterate via next()/done/value.
    // The try/finally ensures the iterator's return() is called when the
    // caller exits the enumeration early (break/return/throw before done).
    private IEnumerable<JsValue> IterateSetRecordKeys(SetRecord rec)
    {
        var iter = CallFunction(rec.Keys, Array.Empty<JsValue>(), rec.Obj);
        if (iter.Tag != JsValueTag.Object)
        {
            throw new JsThrownException(CreateTypeError("Set method: keys() did not return an iterator object."));
        }

        var iterObj = _heap.GetObject(iter.AsObjectHandle());
        if (!TryGetPropertyValue(iterObj, iter, "next", out var next) || !IsCallable(next))
        {
            throw new JsThrownException(CreateTypeError("Set method: keys() iterator has no callable 'next'."));
        }

        bool done = false;
        try
        {
            while (true)
            {
                var res = CallFunction(next, Array.Empty<JsValue>(), iter);
                if (res.Tag != JsValueTag.Object)
                {
                    throw new JsThrownException(CreateTypeError("Set method: iterator result is not an object."));
                }

                var resObj = _heap.GetObject(res.AsObjectHandle());
                TryGetPropertyValue(resObj, res, "done", out var doneVal);
                if (IsTruthy(doneVal))
                {
                    done = true;
                    yield break;
                }

                TryGetPropertyValue(resObj, res, "value", out var val);
                // 24.2.1.2: -0𝔽 keys are normalized to +0𝔽 before use.
                yield return NormalizeSetValue(val);
            }
        }
        finally
        {
            if (!done)
            {
                IteratorCloseOnAbrupt(iter);
            }
        }
    }

    // ECMA-262 invokes the Set-like's own [[Has]] on individual elements.
    private bool CallSetHas(SetRecord rec, JsValue element)
        => IsTruthy(CallFunction(rec.Has, new[] { element }, rec.Obj));

    // -0𝔽 collapses to +0𝔽 for storage in a Set's [[SetData]].
    private static JsValue NormalizeSetValue(JsValue v)
        => v.Tag == JsValueTag.Number && v.AsNumber() == 0.0 && double.IsNegative(v.AsNumber())
            ? JsValue.FromNumber(0.0)
            : v;

    // Set / Map iterator wrappers reuse %ArrayIteratorPrototype% since the only
    // shape it exposes is .next() returning {value, done}; .next reads the source
    // collection's snapshot at iterator-creation time. A fresh snapshot per
    // iterator avoids "mutation during iteration" edge cases the spec actually
    // requires to surface (a future commit can switch to a live cursor).
    private JsValue CreateSetIterator(JsValue receiver, bool isEntries)
    {
        var set = RequireSet(receiver);
        var kind = isEntries ? MapSetIteratorKind.SetEntries : MapSetIteratorKind.SetValues;
        var iter = new LiveMapSetIteratorObject(receiver.AsObjectHandle(), kind);
        iter.SetPrototype(EnsureSetIteratorPrototype());
        return JsValue.FromObject(_heap.AllocateObject(iter, AllocationSite.Current()));
    }

    private enum MapIteratorKind { Key, Value, Entry }

    private JsValue CreateMapIterator(JsValue receiver, MapIteratorKind kind)
    {
        var map = RequireMap(receiver); // validates the receiver is a Map
        var iterKind = kind switch
        {
            MapIteratorKind.Key => MapSetIteratorKind.MapKeys,
            MapIteratorKind.Value => MapSetIteratorKind.MapValues,
            _ => MapSetIteratorKind.MapEntries
        };
        var iter = new LiveMapSetIteratorObject(receiver.AsObjectHandle(), iterKind);
        iter.SetPrototype(EnsureMapIteratorPrototype());
        return JsValue.FromObject(_heap.AllocateObject(iter, AllocationSite.Current()));
    }

    // Shared iterator whose next() reads from a pre-materialised value list. The
    // %ArrayIteratorPrototype% next handler is keyed on ArrayIteratorObject, so
    // for Snapshot iterators we install a tiny shim via DefineOwnProperty('next').
    private sealed class SnapshotIteratorObject : JsObject
    {
        public IReadOnlyList<JsValue> Values { get; }
        public int Index { get; set; }
        public SnapshotIteratorObject(IReadOnlyList<JsValue> values) => Values = values;
    }

    // ECMA-262 24.1.5 / 24.2.5 — live Map/Set iterator. Stores a handle to the
    // source collection and an index cursor; .next() reads from the live entries
    // list so additions during iteration are visible (per spec).
    private sealed class LiveMapSetIteratorObject : JsObject
    {
        public ObjectHandle SourceHandle { get; }
        public int Index { get; set; }
        public bool IsExhausted { get; set; }
        // For Set: Values or Entries. For Map: Keys, Values, or Entries.
        public MapSetIteratorKind Kind { get; }
        public LiveMapSetIteratorObject(ObjectHandle sourceHandle, MapSetIteratorKind kind)
        {
            SourceHandle = sourceHandle;
            Kind = kind;
        }
    }

    private enum MapSetIteratorKind
    {
        SetValues, SetEntries,
        MapKeys, MapValues, MapEntries
    }

    private sealed class SetObject : JsObject
    {
        // Spec uses SameValueZero for entry identity. A List with a manual
        // SameValueZero comparison keeps both spec correctness and trivial GC
        // traceability (entries are reachable via the list).
        internal readonly List<JsValue> _entries = new();

        public int Count => _entries.Count;

        public void Add(JsValue value)
        {
            if (!Has(value))
            {
                _entries.Add(value);
            }
        }

        public bool Has(JsValue value)
        {
            foreach (var e in _entries)
            {
                if (SameValueZero(e, value))
                {
                    return true;
                }
            }

            return false;
        }

        public bool Remove(JsValue value)
        {
            for (var i = 0; i < _entries.Count; i++)
            {
                if (SameValueZero(_entries[i], value))
                {
                    _entries.RemoveAt(i);
                    return true;
                }
            }

            return false;
        }

        public void Clear() => _entries.Clear();

        public IReadOnlyList<JsValue> Snapshot() => _entries.ToArray();
    }

    // ECMA-262 24.3 WeakMap and 24.4 WeakSet. Spec requires keys to be Objects
    // (or non-registered Symbols in newer drafts). Internally we use an
    // ObjectHandle-keyed dictionary so identity matches the spec's "same object".
    // True weak references would require runtime GC-aware semantics; this is a
    // strong-reference shim that satisfies API conformance.
    private ObjectHandle EnsureWeakMapConstructor()
    {
        if (_weakMapConstructorHandle is { } existing)
        {
            return existing;
        }

        var prototype = CreateOrdinaryObject();
        var prototypeHandle = _heap.AllocateObject(prototype, AllocationSite.Current());
        _heap.PushRoot(prototypeHandle);

        var constructor = new NativeFunctionObject(
            "WeakMap",
            (_, _) => throw new JsThrownException(CreateTypeError("Constructor WeakMap requires 'new'.")),
            args =>
            {
                var wm = new WeakMapObject();
                wm.SetPrototype(EnsureWeakMapPrototype());
                var handle = _heap.AllocateObject(wm, AllocationSite.Current());
                _heap.PushRoot(handle);
                try
                {
                    if (args.Count > 0 && args[0].Tag != JsValueTag.Undefined && args[0].Tag != JsValueTag.Null)
                    {
                        var wmValue = JsValue.FromObject(handle);
                        var adder = GetReceiverProperty(wmValue, "set");
                        if (!IsCallable(adder))
                            throw new JsThrownException(CreateTypeError("WeakMap.prototype.set is not callable."));
                        var iter = CreateForOfIteratorState(args[0], requireIterable: true);
                        if (iter.Tag != JsValueTag.Object || _heap.GetObject(iter.AsObjectHandle()) is not ForOfIteratorObject forOf)
                            throw new JsThrownException(CreateTypeError("WeakMap constructor requires an iterable."));
                        try
                        {
                            while (!ForOfStepDone(forOf, out var entry))
                            {
                                // Entry must be an Object per spec — non-object
                                // (Symbol, null, undefined, string) → TypeError + close.
                                if (entry.Tag != JsValueTag.Object)
                                    throw new JsThrownException(CreateTypeError("WeakMap iterator value is not an object."));
                                PinIfObject(entry);
                                var entryObj = _heap.GetObject(entry.AsObjectHandle());
                                TryGetPropertyValue(entryObj, entry, "0", out var key);
                                TryGetPropertyValue(entryObj, entry, "1", out var val);
                                _ = CallFunction(adder, new[] { key, val }, wmValue);
                            }
                        }
                        finally
                        {
                            try { CloseForOfIteratorState(forOf); } catch (JsThrownException) { }
                        }
                    }
                }
                finally
                {
                    _heap.PopRootsTo(_heap.RootCount - 1);
                }
                return JsValue.FromObject(handle);
            },
            length: 0);

        _ = constructor.DefineOwnProperty("prototype", new JsPropertyDescriptor(JsValue.FromObject(prototypeHandle), Writable: false, Enumerable: false, Configurable: false));
        constructor.SetPrototype(EnsureFunctionPrototype());
        var constructorHandle = _heap.AllocateObject(constructor, AllocationSite.Current());
        _heap.PushRoot(constructorHandle);
        _ = prototype.DefineOwnProperty("constructor", new JsPropertyDescriptor(JsValue.FromObject(constructorHandle), Writable: true, Enumerable: false, Configurable: true));
        _heap.WriteBarrier(prototypeHandle, constructorHandle);

        // ECMA-262 24.3.3.1 WeakMap.prototype [ @@toStringTag ] = "WeakMap"
        DefineBuiltinToStringTag(prototype, "WeakMap");

        DefineNativePrototypeMethod(prototypeHandle, prototype, "set", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            var val = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (!CanBeHeldWeakly(key))
            {
                throw new JsThrownException(CreateTypeError("Invalid value used as weak map key."));
            }

            WeakMapSet(thisValue.AsObjectHandle(), wm, key, val);
            return thisValue;
        }, length: 2);

        DefineNativePrototypeMethod(prototypeHandle, prototype, "get", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            return WeakMapTryGet(wm, key, out var v) ? v : JsValue.Undefined;
        }, length: 1);

        // WeakMap.prototype.getOrInsert(key, value) — Upsert proposal.
        DefineNativePrototypeMethod(prototypeHandle, prototype, "getOrInsert", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            var val = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (!CanBeHeldWeakly(key))
            {
                throw new JsThrownException(CreateTypeError("Invalid value used as weak map key."));
            }
            if (WeakMapTryGet(wm, key, out var existing)) return existing;
            WeakMapSet(thisValue.AsObjectHandle(), wm, key, val);
            return val;
        }, length: 2);

        // WeakMap.prototype.getOrInsertComputed(key, callbackfn) — Upsert proposal.
        // The key is validated before the callback; a throwing callback leaves the
        // map unchanged.
        DefineNativePrototypeMethod(prototypeHandle, prototype, "getOrInsertComputed", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            var callback = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (!CanBeHeldWeakly(key))
            {
                throw new JsThrownException(CreateTypeError("Invalid value used as weak map key."));
            }
            if (!IsCallable(callback))
            {
                throw new JsThrownException(CreateTypeError(
                    "WeakMap.prototype.getOrInsertComputed: callbackfn is not callable."));
            }
            if (WeakMapTryGet(wm, key, out var existing)) return existing;
            var val = CallFunction(callback, new[] { key }, JsValue.Undefined);
            WeakMapSet(thisValue.AsObjectHandle(), wm, key, val);
            return val;
        }, length: 2);

        DefineNativePrototypeMethod(prototypeHandle, prototype, "has", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            return JsValue.FromBoolean(WeakMapHas(wm, key));
        }, length: 1);

        DefineNativePrototypeMethod(prototypeHandle, prototype, "delete", (thisValue, args) =>
        {
            var wm = RequireWeakMap(thisValue);
            var key = args.Count > 0 ? args[0] : JsValue.Undefined;
            return JsValue.FromBoolean(WeakMapRemove(wm, key));
        }, length: 1);

        _weakMapPrototypeHandle = prototypeHandle;
        _weakMapConstructorHandle = constructorHandle;
        return constructorHandle;
    }

    private ObjectHandle EnsureWeakMapPrototype()
    {
        _ = EnsureWeakMapConstructor();
        return _weakMapPrototypeHandle!.Value;
    }

    private WeakMapObject RequireWeakMap(JsValue thisValue)
    {
        if (thisValue.Tag != JsValueTag.Object)
            throw new JsThrownException(CreateTypeError("WeakMap method called on incompatible receiver."));
        var obj = _heap.GetObject(thisValue.AsObjectHandle());
        if (obj is WeakMapObject wm)
            return wm;
        // Accept subclass instances whose prototype chain includes %WeakMap.prototype%.
        if (IsPrototypeOf(EnsureWeakMapPrototype(), obj))
            return (WeakMapObject)obj;
        throw new JsThrownException(CreateTypeError("WeakMap method called on incompatible receiver."));
    }

    // ECMA-262 CanBeHeldWeakly(v): an Object can always be held weakly; a Symbol
    // can be held weakly only when it is NOT in the GlobalSymbolRegistry (i.e. not
    // produced by Symbol.for). Used as the key/target validity test for WeakMap,
    // WeakSet, WeakRef and FinalizationRegistry.
    private bool CanBeHeldWeakly(JsValue v)
    {
        if (v.Tag == JsValueTag.HostObject) return true;
        if (v.Tag == JsValueTag.Object) return true;
        if (v.Tag == JsValueTag.Symbol) return !_symbolRegistryById.ContainsKey(v.AsSymbolId());
        return false;
    }

    // Object- or Symbol-keyed access helpers for a WeakMap (callers validate the
    // key with CanBeHeldWeakly first).
    private static bool WeakMapTryGet(WeakMapObject wm, JsValue key, out JsValue value)
    {
        if (key.Tag == JsValueTag.Object) return wm.TryGet(key.AsObjectHandle(), out value);
        if (key.Tag == JsValueTag.HostObject) return wm.TryGetHost(key.AsHostObjectHandle(), out value);
        if (key.Tag == JsValueTag.Symbol) return wm.TryGetSymbol(key.AsSymbolId(), out value);
        value = JsValue.Undefined;
        return false;
    }

    private static bool WeakMapHas(WeakMapObject wm, JsValue key)
        => key.Tag == JsValueTag.Object ? wm.Has(key.AsObjectHandle())
         : key.Tag == JsValueTag.HostObject ? wm.HasHost(key.AsHostObjectHandle())
         : key.Tag == JsValueTag.Symbol && wm.HasSymbol(key.AsSymbolId());

    private static bool WeakMapRemove(WeakMapObject wm, JsValue key)
        => key.Tag == JsValueTag.Object ? wm.Remove(key.AsObjectHandle())
         : key.Tag == JsValueTag.HostObject ? wm.RemoveHost(key.AsHostObjectHandle())
         : key.Tag == JsValueTag.Symbol && wm.RemoveSymbol(key.AsSymbolId());

    private void WeakMapSet(ObjectHandle wmHandle, WeakMapObject wm, JsValue key, JsValue val)
    {
        if (key.Tag == JsValueTag.Object)
        {
            wm.Set(key.AsObjectHandle(), val);
            _heap.WriteBarrier(wmHandle, key.AsObjectHandle());
        }
        else if (key.Tag == JsValueTag.HostObject)
        {
            wm.SetHost(key.AsHostObjectHandle(), val);
        }
        else
        {
            wm.SetSymbol(key.AsSymbolId(), val);
        }
        if (val.Tag == JsValueTag.Object) _heap.WriteBarrier(wmHandle, val.AsObjectHandle());
    }

    private ObjectHandle EnsureWeakSetConstructor()
    {
        if (_weakSetConstructorHandle is { } existing)
        {
            return existing;
        }

        var prototype = CreateOrdinaryObject();
        var prototypeHandle = _heap.AllocateObject(prototype, AllocationSite.Current());
        _heap.PushRoot(prototypeHandle);

        var constructor = new NativeFunctionObject(
            "WeakSet",
            (_, _) => throw new JsThrownException(CreateTypeError("Constructor WeakSet requires 'new'.")),
            args =>
            {
                var ws = new WeakSetObject();
                ws.SetPrototype(EnsureWeakSetPrototype());
                var handle = _heap.AllocateObject(ws, AllocationSite.Current());
                _heap.PushRoot(handle);
                try
                {
                    if (args.Count > 0 && args[0].Tag != JsValueTag.Undefined && args[0].Tag != JsValueTag.Null)
                    {
                        var wsValue = JsValue.FromObject(handle);
                        var adder = GetReceiverProperty(wsValue, "add");
                        if (!IsCallable(adder))
                            throw new JsThrownException(CreateTypeError("WeakSet.prototype.add is not callable."));
                        var iter = CreateForOfIteratorState(args[0], requireIterable: true);
                        if (iter.Tag != JsValueTag.Object || _heap.GetObject(iter.AsObjectHandle()) is not ForOfIteratorObject forOf)
                            throw new JsThrownException(CreateTypeError("WeakSet constructor requires an iterable."));
                        try
                        {
                            while (!ForOfStepDone(forOf, out var v))
                            {
                                // Call adder first — it validates the value (WeakSet.add
                                // throws TypeError for non-objects). If adder is overridden,
                                // the override's error should propagate per spec.
                                _ = CallFunction(adder, new[] { v }, wsValue);
                            }
                        }
                        finally
                        {
                            try { CloseForOfIteratorState(forOf); } catch (JsThrownException) { }
                        }
                    }
                }
                finally
                {
                    _heap.PopRootsTo(_heap.RootCount - 1);
                }
                return JsValue.FromObject(handle);
            },
            length: 0);

        _ = constructor.DefineOwnProperty("prototype", new JsPropertyDescriptor(JsValue.FromObject(prototypeHandle), Writable: false, Enumerable: false, Configurable: false));
        constructor.SetPrototype(EnsureFunctionPrototype());
        var constructorHandle = _heap.AllocateObject(constructor, AllocationSite.Current());
        _heap.PushRoot(constructorHandle);
        _ = prototype.DefineOwnProperty("constructor", new JsPropertyDescriptor(JsValue.FromObject(constructorHandle), Writable: true, Enumerable: false, Configurable: true));
        _heap.WriteBarrier(prototypeHandle, constructorHandle);

        // ECMA-262 24.4.3.1 WeakSet.prototype [ @@toStringTag ] = "WeakSet"
        DefineBuiltinToStringTag(prototype, "WeakSet");

        DefineNativePrototypeMethod(prototypeHandle, prototype, "add", (thisValue, args) =>
        {
            var ws = RequireWeakSet(thisValue);
            var value = args.Count > 0 ? args[0] : JsValue.Undefined;
            if (!CanBeHeldWeakly(value))
            {
                throw new JsThrownException(CreateTypeError("Invalid value used in weak set."));
            }

            if (value.Tag == JsValueTag.Object)
            {
                ws.Add(value.AsObjectHandle());
                _heap.WriteBarrier(thisValue.AsObjectHandle(), value.AsObjectHandle());
            }
            else if (value.Tag == JsValueTag.HostObject)
            {
                ws.AddHost(value.AsHostObjectHandle());
            }
            else
            {
                ws.AddSymbol(value.AsSymbolId());
            }
            return thisValue;
        }, length: 1);

        DefineNativePrototypeMethod(prototypeHandle, prototype, "has", (thisValue, args) =>
        {
            var ws = RequireWeakSet(thisValue);
            var value = args.Count > 0 ? args[0] : JsValue.Undefined;
            var present = value.Tag == JsValueTag.Object ? ws.Has(value.AsObjectHandle())
                        : value.Tag == JsValueTag.HostObject ? ws.HasHost(value.AsHostObjectHandle())
                        : value.Tag == JsValueTag.Symbol && ws.HasSymbol(value.AsSymbolId());
            return JsValue.FromBoolean(present);
        }, length: 1);

        DefineNativePrototypeMethod(prototypeHandle, prototype, "delete", (thisValue, args) =>
        {
            var ws = RequireWeakSet(thisValue);
            var value = args.Count > 0 ? args[0] : JsValue.Undefined;
            var removed = value.Tag == JsValueTag.Object ? ws.Remove(value.AsObjectHandle())
                        : value.Tag == JsValueTag.HostObject ? ws.RemoveHost(value.AsHostObjectHandle())
                        : value.Tag == JsValueTag.Symbol && ws.RemoveSymbol(value.AsSymbolId());
            return JsValue.FromBoolean(removed);
        }, length: 1);

        _weakSetPrototypeHandle = prototypeHandle;
        _weakSetConstructorHandle = constructorHandle;
        return constructorHandle;
    }

    private ObjectHandle EnsureWeakSetPrototype()
    {
        _ = EnsureWeakSetConstructor();
        return _weakSetPrototypeHandle!.Value;
    }

    private WeakSetObject RequireWeakSet(JsValue thisValue)
    {
        if (thisValue.Tag != JsValueTag.Object ||
            _heap.GetObject(thisValue.AsObjectHandle()) is not WeakSetObject ws)
        {
            throw new JsThrownException(CreateTypeError("WeakSet method called on incompatible receiver."));
        }

        return ws;
    }

    private sealed class WeakMapObject : JsObject
    {
        private readonly Dictionary<ObjectHandle, JsValue> _entries = new();
        private readonly Dictionary<HostObjectHandle, JsValue> _hostEntries = new();
        // ECMA-262: a non-registered Symbol can also be held weakly.
        private readonly Dictionary<long, JsValue> _symbolEntries = new();
        public void Set(ObjectHandle key, JsValue value) => _entries[key] = value;
        public bool TryGet(ObjectHandle key, out JsValue value) => _entries.TryGetValue(key, out value);
        public bool Has(ObjectHandle key) => _entries.ContainsKey(key);
        public bool Remove(ObjectHandle key) => _entries.Remove(key);
        public void SetHost(HostObjectHandle key, JsValue value) => _hostEntries[key] = value;
        public bool TryGetHost(HostObjectHandle key, out JsValue value) => _hostEntries.TryGetValue(key, out value);
        public bool HasHost(HostObjectHandle key) => _hostEntries.ContainsKey(key);
        public bool RemoveHost(HostObjectHandle key) => _hostEntries.Remove(key);
        public void SetSymbol(long id, JsValue value) => _symbolEntries[id] = value;
        public bool TryGetSymbol(long id, out JsValue value) => _symbolEntries.TryGetValue(id, out value);
        public bool HasSymbol(long id) => _symbolEntries.ContainsKey(id);
        public bool RemoveSymbol(long id) => _symbolEntries.Remove(id);
    }

    private sealed class WeakSetObject : JsObject
    {
        private readonly HashSet<ObjectHandle> _entries = new();
        private readonly HashSet<HostObjectHandle> _hostEntries = new();
        private readonly HashSet<long> _symbolEntries = new();
        public void Add(ObjectHandle key) => _entries.Add(key);
        public bool Has(ObjectHandle key) => _entries.Contains(key);
        public bool Remove(ObjectHandle key) => _entries.Remove(key);
        public void AddHost(HostObjectHandle key) => _hostEntries.Add(key);
        public bool HasHost(HostObjectHandle key) => _hostEntries.Contains(key);
        public bool RemoveHost(HostObjectHandle key) => _hostEntries.Remove(key);
        public void AddSymbol(long id) => _symbolEntries.Add(id);
        public bool HasSymbol(long id) => _symbolEntries.Contains(id);
        public bool RemoveSymbol(long id) => _symbolEntries.Remove(id);
    }

    // ECMA-262 28.1 The Reflect Object. Most members are thin wrappers over the
    // same internal helpers Object.* use; the spec-mandated differences are that
    // Reflect.set / defineProperty / deleteProperty return booleans (matching
    // the underlying [[Set]] / [[DefineOwnProperty]] / [[Delete]] success
    // result) instead of throwing.
    private ObjectHandle EnsureReflectObject()
    {
        if (_reflectObjectHandle is { } existing)
        {
            return existing;
        }

        var reflect = CreateOrdinaryObject();
        var handle = _heap.AllocateObject(reflect, AllocationSite.Current());
        _heap.PushRoot(handle);

        // 28.1.9 has
        DefineIntrinsicFunction(handle, reflect, "has", (_, args) =>
        {
            RequireObjectTarget(args, "Reflect.has");
            var obj = _heap.GetObject(args[0].AsObjectHandle());
            var keyArg = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (keyArg.Tag == JsValueTag.Symbol)
            {
                return JsValue.FromBoolean(obj.TryGetSymbolProperty(keyArg.AsSymbolId(), h => _heap.GetObject(h), out JsPropertyDescriptor _));
            }
            var key = ToPropertyKey(keyArg);
            // ECMA-262 28.1.9 Reflect.has → target.[[HasProperty]]: a Proxy must run
            // its "has" trap rather than a plain ordinary lookup.
            if (obj is ProxyObject hasProxy)
            {
                return JsValue.FromBoolean(ProxyHas(hasProxy, key));
            }
            // Use HasPropertyIncludingProxy for correct TypedArray exotic [[HasProperty]]
            // behavior (e.g., "-0" key returns false per aligned spec).
            return JsValue.FromBoolean(HasPropertyIncludingProxy(obj, key));
        }, length: 2);

        // 28.1.6 get
        // ECMA-262 28.1.6 Reflect.get(target, key [, receiver]): receiver
        // defaults to target. The property lookup uses target; the receiver
        // is passed as `this` to accessor getters.
        DefineIntrinsicFunction(handle, reflect, "get", (_, args) =>
        {
            RequireObjectTarget(args, "Reflect.get");
            var target = args[0];
            var receiver = args.Count > 2 ? args[2] : target;
            var keyArg = args.Count > 1 ? args[1] : JsValue.Undefined;
            if (keyArg.Tag == JsValueTag.Symbol)
                return GetReceiverSymbolProperty(receiver, keyArg.AsSymbolId());
            var key = ToPropertyKey(keyArg);
            return GetReceiverPropertyWithReceiver(target, receiver, key);
        }, length: 2);

        // 28.1.14 set
        DefineIntrinsicFunction(handle, reflect, "set", (_, args) =>
        {
            RequireObjectTarget(args, "Reflect.set");
            var targetHandle = args[0].AsObjectHandle();
            var obj = _heap.GetObject(targetHandle);
            var keyArg = args.Count > 1 ? args[1] : JsValue.Undefined;
            var value = args.Count > 2 ? args[2] : JsValue.Undefined;
            // ECMA-262 28.1.13 Reflect.set(target, key, V, receiver): receiver
            // defaults to target. A Proxy target routes through its "set" trap so
            // the boolean trap result (and its invariants) are observed.
            var receiver = args.Count > 3 ? args[3] : args[0];
            if (keyArg.Tag == JsValueTag.Symbol)
            {
                return JsValue.FromBoolean(SetSymbolPropertyValue(targetHandle, obj, keyArg.AsSymbolId(), value, receiver));
            }
            var key = ToPropertyKey(keyArg);
            if (obj is ProxyObject reflectProxy)
            {
                return JsValue.FromBoolean(ProxySet(reflectProxy, receiver, key, value));
