    // ECMA-262 19.2.1.3 EvalDeclarationInstantiation ( body, varEnv, lexEnv, privateEnv, strict )
    // Validates that the eval body's declarations don't conflict with the calling
    // context's environment. Throws SyntaxError for violations.
    private static bool ContainsSuperRecursive(BytecodeFunction fn)
    {
        foreach (var ins in fn.Instructions)
        {
            if (ins.OpCode == OpCode.LoadSuperProperty ||
                ins.OpCode == OpCode.LoadSuperConstructor ||
                ins.OpCode == OpCode.LoadSuperElement ||
                ins.OpCode == OpCode.InitThisBinding)
                return true;
        }
        foreach (var nested in fn.NestedFunctions)
            if (ContainsSuperRecursive(nested)) return true;
        return false;
    }

    private static bool ContainsArgumentsRecursive(BytecodeFunction fn)
    {
        foreach (var name in fn.PropertyNames)
            if (name == "arguments") return true;
        foreach (var nested in fn.NestedFunctions)
            if (ContainsArgumentsRecursive(nested)) return true;
        return false;
    }

    private void ValidateEvalDeclarations(BytecodeFunction compiled, EnvironmentRecord? callingEnv, bool strict)
    {
        // ECMA-262 19.2.1.3: super references in eval are allowed when the
        // calling context has a super binding (direct eval inside a class
        // method/constructor). Otherwise they are a SyntaxError.
        // ECMA-262: Additional Early Error Rules for Eval Outside Constructor Methods.
        // If the eval body (or any nested function/arrow) contains SuperCall or
        // SuperProperty, it is a SyntaxError when the calling context does not have
        // a valid super binding (i.e., outside a derived constructor/method).
        // Recursively scan nested functions so that `() => super()` inside eval
        // is caught even when the arrow is not immediately invoked.
        var hasSuper = ContainsSuperRecursive(compiled);
        if (hasSuper)
        {
            var fenv = callingEnv as FunctionEnvironmentRecord;
            var hasSuperBinding = fenv is not null && fenv.HasSuperBinding;
            // ECMA-262: super references in eval are only valid inside a derived
            // constructor body AFTER the super() call. In all other contexts
            // (methods, field initializers, ordinary functions), reject.
            if (!hasSuperBinding)
                throw new JsThrownException(CreateSyntaxError("'super' cannot be used in eval."));
            // If we have a super binding but the this binding is uninitialized,
            // we are in a field initializer or before super() in the constructor.
            if (fenv!.ThisBindingStatus == ThisBindingStatus.Uninitialized)
                throw new JsThrownException(CreateSyntaxError("'super' cannot be used in eval before super() is called."));
            // In a method (not a constructor), super() as a call is never valid.
            var callerFrame = _activeFrames.Count > 0 ? _activeFrames.Peek() : null;
            if (callerFrame?.Function?.Kind != FunctionKind.Constructor)
                throw new JsThrownException(CreateSyntaxError("'super' cannot be used in eval inside a method."));
        }

        // ECMA-262: Additional Early Error Rules for Eval Inside Initializer.
        // If the eval body (or any nested function/arrow) contains an 'arguments'
        // reference, it is a SyntaxError when direct eval is called inside a class
        // field initializer. Recursively scan all nested functions.
        if (callingEnv is not null && _activeFrames.Count > 0 && _activeFrames.Peek().Function?.Kind == FunctionKind.Constructor)
        {
            if (ContainsArgumentsRecursive(compiled))
                throw new JsThrownException(CreateSyntaxError(
                    "'arguments' cannot be used in eval inside a class field initializer."));
        }

        // Collect all var-scoped and function declarations from the eval body.
        var varNames = new HashSet<string>(compiled.VarDeclarationNames);
        var lexNames = new HashSet<string>(compiled.LexicalDeclarationNames);
        var constNames = new HashSet<string>(compiled.ConstDeclarationNames);
        // Function declarations are hoisted as vars in eval (recorded in VarDeclarationNames).

        // ECMA-262 19.2.1.3: in a non-strict direct eval inside a function
        // context whose [[ThisMode]] is not lexical, var/function declarations
        // named `arguments` are a SyntaxError regardless of whether the calling
        // function already has an `arguments` binding.
        // Arrow functions are exempt: they do not create a
        // FunctionEnvironmentRecord (they inherit the enclosing scope's env),
        // and their [[ThisMode]] is lexical.
        // Strict eval has its own scope, so this restriction does not apply.
        if (!strict && callingEnv is FunctionEnvironmentRecord &&
            varNames.Contains("arguments"))
        {
            throw new JsThrownException(CreateSyntaxError(
                "Cannot declare 'arguments' in a direct eval inside a function."));
        }

        // Step 6-14: for non-strict direct eval, var/function declarations must not
        // conflict with existing lexical bindings in any outer scope.
        if (!strict && callingEnv is not null)
        {
            var callingFunction = _activeFrames.Count > 0
                ? _activeFrames.Peek().Function
                : null;
            var env = callingEnv;
            while (env is not null)
            {
                if (env is DeclarativeEnvironmentRecord declEnv)
                {
                    // ECMA-262 19.2.1.3 step 7: the varEnv (FunctionEnvironmentRecord)
                    // is NOT checked for lexical conflicts — var declarations that
                    // shadow the varEnv's bindings are handled later (silently skipped
                    // in InstantiateVarDeclarations per step 8).
                    if (env is FunctionEnvironmentRecord)
                    {
                        foreach (var name in varNames)
                        {
                            if (declEnv.HasBinding(name))
                            {
                                bool isParameter = callingFunction is not null &&
                                    callingFunction.ParameterNames.Contains(name, StringComparer.Ordinal);
                                if (!isParameter)
                                {
                                    // ECMA-262 19.2.1.3 step 8.c.iii: the existing
                                    // binding is NOT from a FormalParameter.
                                    // Check whether the calling function explicitly
                                    // declares this name — a function declaration,
                                    // var, let, or const in the body all block an
                                    // eval-introduced var of the same name.
                                    // We consult the calling function's own
                                    // declaration lists rather than the env record's
                                    // deletability flag because the implicit
                                    // `arguments` object (non-deletable) may already
                                    // occupy the slot before the body-level
                                    // declaration is instantiated.
                                    bool isExplicitBinding = callingFunction is not null &&
                                        (callingFunction.VarDeclarationNames.Contains(name) ||
                                         callingFunction.LexicalDeclarationNames.Contains(name) ||
                                         callingFunction.ConstDeclarationNames.Contains(name));
                                    if (isExplicitBinding)
                                    {
                                        throw new JsThrownException(CreateSyntaxError(
                                            $"Cannot declare var binding '{name}' — a binding with that name already exists."));
                                    }
                                }
                                else if (callingFunction is not null &&
                                    callingFunction.PrologueEndIp > 0 &&
                                    _activeFrames.Count > 0)
                                {
                                    // Step 8.c.iv + 8.e: parameter binding conflict
                                    // — only illegal when eval is in the parameter
                                    // scope (before prologue ends).
                                    var callingFrame = _activeFrames.Peek();
                                    if (callingFrame.InstructionPointer <= callingFunction.PrologueEndIp)
                                    {
                                        throw new JsThrownException(CreateSyntaxError(
                                            $"Cannot declare var binding '{name}' — a parameter binding with that name already exists and the var was introduced by a direct eval call in the parameter scope."));
                                    }
                                }
                            }
                        }
                    }
                    else
                    {
                        foreach (var name in varNames)
                        {
                            if (declEnv.HasLexicalBinding(name))
                                throw new JsThrownException(CreateSyntaxError(
                                    $"Cannot declare var binding '{name}' — a lexical binding with that name already exists."));
                        }
                    }
                }
                env = env.OuterEnv;
            }
        }

        // Step 15-18: lexical (let/const) declarations must not conflict with any
        // existing binding in the same var scope.
        if (callingEnv is DeclarativeEnvironmentRecord callingDecl)
        {
            var allLexNames = new HashSet<string>(lexNames);
            foreach (var n in constNames) allLexNames.Add(n);
            foreach (var name in allLexNames)
            {
                if (callingDecl.HasBinding(name))
                    throw new JsThrownException(CreateSyntaxError(
                        $"Cannot declare lexical binding '{name}' — a binding with that name already exists."));
            }
        }
    }

