    // Shared engine for Date setFullYear / setMonth / setDate. Reads the current
    // [[DateValue]] (substituting epoch when NaN, matching the spec's MakeDay
    // step), overwrites the requested portions from args, and writes back through
    // TimeClip. Any non-finite component drives the result to NaN per the
    // spec's MakeDate failure mode.
    private static JsValue ArgOrUndefined(IReadOnlyList<JsValue> args, int index)
        => index >= 0 && index < args.Count ? args[index] : JsValue.Undefined;

    private JsValue SetDateField(
        JsValue thisValue, string method, IReadOnlyList<JsValue> args,
        bool hasYear, bool hasMonth, bool hasDay,
        int yearArgIndex = 0, int monthArgIndex = 1, int dayArgIndex = 2)
    {
        var date = RequireDate(thisValue, method);

        // ECMA-262 21.4.4.21/.20/.19: the [[DateValue]] is read FIRST (step 3), then
        // every provided argument is ToNumber-coerced in argument order. So a NaN
        // Date still observes each valueOf once, and a callback that mutates the Date
        // mid-coercion does not change the captured time the result is built from.
        // A required field with no corresponding argument is ToNumber(undefined) =
        // NaN (e.g. `setFullYear()` yields an Invalid Date), so read missing slots as
        // undefined rather than indexing past the argument list.
        var capturedT = date.TimeValue;
        double? yearArg = hasYear ? ToNumber(ArgOrUndefined(args, yearArgIndex)) : null;
        double? monthArg = hasMonth ? ToNumber(ArgOrUndefined(args, monthArgIndex)) : null;
        double? dayArg = hasDay ? ToNumber(ArgOrUndefined(args, dayArgIndex)) : null;

        double baseT;
        if (double.IsFinite(capturedT))
        {
            baseT = capturedT;
        }
        else if (hasYear)
        {
            // setFullYear is allowed to resurrect a NaN-valued Date per spec 21.4.4.21
            // step 2: "If t is NaN, set t to +0".
            baseT = 0;
        }
        else
        {
            // The captured time was NaN and this setter cannot resurrect it: the
            // result is NaN, but [[DateValue]] is left as-is (it is already NaN,
            // unless an argument's valueOf mutated it mid-coercion — that write is
            // preserved, matching the time-field setters).
            return JsValue.FromNumber(double.NaN);
        }

        // Read the untouched portions from the current time; overwrite the requested
        // ones with the already-coerced argument values, then recompose via
        // MakeDay/MakeDate. MakeDay overflow handles Feb 30 etc.
        double year = yearArg ?? DateMath.YearFromTime(baseT);
        double month = monthArg ?? DateMath.MonthFromTime(baseT);
        double day = dayArg ?? DateMath.DateFromTime(baseT);

        var newDay = DateMath.MakeDay(year, month, day);
        date.TimeValue = DateMath.TimeClip(DateMath.MakeDate(newDay, DateMath.TimeWithinDay(baseT)));
        return JsValue.FromNumber(date.TimeValue);
    }

    // Shared engine for setHours / setMinutes / setSeconds / setMilliseconds.
    // startIndex picks the most significant portion the call writes (0=hour,
    // 1=minute, 2=second, 3=millisecond); the call may also provide every
    // lower-order portion after it. Anything not provided keeps its existing value.
    private JsValue SetTimeField(JsValue thisValue, string method, IReadOnlyList<JsValue> args, int startIndex)
    {
        var date = RequireDate(thisValue, method);
        // ECMA-262 21.4.4.34/.33/.32/.31: read the [[DateValue]] FIRST, then ToNumber
        // every provided argument in argument order (so a NaN Date still observes each
        // valueOf once, and a callback mutating the Date can't change the captured time).
        var t0 = date.TimeValue;
        var provided = new double[4];
        var has = new bool[4];
        // The most-significant component (at startIndex) is the required argument and
        // is always ToNumber-coerced — `setHours()` with no argument is ToNumber(
        // undefined) = NaN, yielding an Invalid Date. Lower-order components are only
        // overwritten when actually supplied.
        provided[startIndex] = ToNumber(ArgOrUndefined(args, 0));
        has[startIndex] = true;
        for (var i = 1; i < args.Count && startIndex + i < 4; i++)
        {
            provided[startIndex + i] = ToNumber(args[i]);
            has[startIndex + i] = true;
        }
        if (!double.IsFinite(t0))
        {
            return JsValue.FromNumber(double.NaN);
        }
        // Untouched portions keep their current value; provided args overwrite from startIndex.
        var components = new double[]
        {
            DateMath.HoursFromTime(t0), DateMath.MinFromTime(t0),
            DateMath.SecFromTime(t0), DateMath.MsFromTime(t0)
        };
        for (var i = 0; i < 4; i++)
        {
            if (has[i]) components[i] = provided[i];
        }
        var time = DateMath.MakeTime(components[0], components[1], components[2], components[3]);
        date.TimeValue = DateMath.TimeClip(DateMath.MakeDate(DateMath.Day(t0), time));
        return JsValue.FromNumber(date.TimeValue);
    }

    // ECMA-262 21.4.1.31 TimeClip - returns NaN for non-finite or out-of-range
    // |t| > 8.64e15, otherwise integer-truncates toward zero.
    private static double TimeClip(double t)
    {
        if (!double.IsFinite(t) || Math.Abs(t) > 8.64e15) return double.NaN;
        return t >= 0 ? Math.Floor(t) : -Math.Floor(-t);
    }

    private void InstallPrototypeMethodsOnDatePrototype(ObjectHandle prototypeHandle, JsObject prototype)
    {
        _ = DefineNativePrototypeMethod(prototypeHandle, prototype, "getTime", DatePrototypeGetTime);
        _ = DefineNativePrototypeMethod(prototypeHandle, prototype, "valueOf", DatePrototypeGetTime);

        _ = DefineNativePrototypeMethod(prototypeHandle, prototype, "setTime", (thisValue, args) =>
