    /// <summary>Simplified GetSubstitution for the spec-based @@replace path.</summary>
    private string GetSubstitutionSpec(string input, string matched, int position, List<JsValue> captures, JsValue namedCaptures, string replacement)
    {
        var sb = new System.Text.StringBuilder();
        for (var i = 0; i < replacement.Length; i++)
        {
            if (replacement[i] == '$' && i + 1 < replacement.Length)
            {
                var c = replacement[i + 1];
                switch (c)
                {
                    case '$': sb.Append('$'); i++; break;
                    case '&': sb.Append(matched); i++; break;
                    case '`': sb.Append(input.AsSpan(0, position)); i++; break;
                    case '\'': sb.Append(input.AsSpan(position + matched.Length)); i++; break;
                    case '<':
                        var eb = replacement.IndexOf('>', i + 2);
                        if (namedCaptures.Tag == JsValueTag.Undefined)
                        {
                            sb.Append('$'); sb.Append('<'); i++;
                        }
                        else if (eb >= 0)
                        {
                            var groupName = replacement.Substring(i + 2, eb - i - 2);
                            var namedObj = _heap.GetObject(namedCaptures.AsObjectHandle());
                            if (TryGetPropertyValue(namedObj, namedCaptures, groupName, out var capture) &&
                                capture.Tag != JsValueTag.Undefined)
                            {
                                sb.Append(ToStringValue(capture));
                            }
                            i = eb;
                        }
                        else { sb.Append('$'); sb.Append('<'); i++; }
                        break;
                    default:
                        if (c >= '0' && c <= '9')
                        {
                            var first = c - '0';
                            if (i + 2 < replacement.Length &&
                                replacement[i + 2] >= '0' &&
                                replacement[i + 2] <= '9')
                            {
                                var second = replacement[i + 2] - '0';
                                var twoDigit = first * 10 + second;
                                if (twoDigit != 0 && twoDigit <= captures.Count)
                                {
                                    AppendCaptureSubstitution(sb, captures[twoDigit - 1]);
                                    i += 2;
                                    break;
                                }
                            }

                            if (first == 0)
                            {
                                sb.Append('$');
                                sb.Append(c);
                                i++;
                                break;
                            }

                            if (first <= captures.Count)
                            {
                                AppendCaptureSubstitution(sb, captures[first - 1]);
                                i++;
                            }
                            else
                            {
                                sb.Append('$');
                                sb.Append(c);
                                i++;
                            }
                        }
                        else { sb.Append('$'); i++; sb.Append(c); }
                        break;
                }
            }
            else sb.Append(replacement[i]);
        }
        return sb.ToString();
    }

    private void AppendCaptureSubstitution(System.Text.StringBuilder sb, JsValue capture)
    {
        if (capture.Tag != JsValueTag.Undefined)
        {
            sb.Append(ToStringValue(capture));
        }
    }

