            var eDouble = ToLengthNumber(lastIndexVal);
            int eGen = eDouble >= input.Length ? input.Length : (int)eDouble;
            // 24.f.ii was already checked (exception would propagate)
            // 24.f.iii: If e = p, set q = q + 1 (advance past empty match)
