        throw new JsThrownException(CreateTypeError("RegExp.prototype method called on incompatible receiver."));
    }

    // ECMA-262 22.2.5.2.1 RegExpExec ( R, S ).
    // Calls the "exec" method of R with argument S. Works on any Object, not just RegExp.
    private JsValue RegExpExec(JsValue R, string S)
    {
        // 1. Let exec be ? Get(R, "exec").
        if (R.Tag != JsValueTag.Object || !TryGetPropertyValue(_heap.GetObject(R.AsObjectHandle()), R, "exec", out var execFn))
        {
            throw new JsThrownException(CreateTypeError("RegExpExec: 'exec' property not found."));
        }
        // 2. If IsCallable(exec) is true, then
        if (IsCallable(execFn))
        {
            // a. Let result be ? Call(exec, R, « S »).
            var result = CallFunction(execFn, new[] { JsValue.FromString(S) }, R);
            // b. If Type(result) is neither Object nor Null, throw a TypeError exception.
            if (result.Tag != JsValueTag.Object && result.Tag != JsValueTag.Null)
            {
                throw new JsThrownException(CreateTypeError("RegExpExec: exec must return object or null."));
            }
            // c. Return result.
            return result;
        }
        // 3. Perform ? RequireInternalSlot(R, [[RegExpMatcher]]).
        // ...fall through to built-in exec for RegExp objects.
        if (R.Tag != JsValueTag.Object || _heap.GetObject(R.AsObjectHandle()) is not RegExpObject builtinRegexp)
        {
            throw new JsThrownException(CreateTypeError("RegExpExec: R is not a RegExp and has no callable exec."));
        }
        // 4. Return ? RegExpBuiltinExec(R, S).
        var execResult = RegExpPrototypeExec(R, new[] { JsValue.FromString(S) });
        return execResult;
    }

    // Annex B B.2.4: update legacy static properties after a regex match.
    private void UpdateRegExpLegacyState(string input, JsValue result)
    {
        RegExpBuiltin.LastRegExpInput = input;
        if (result.Tag == JsValueTag.Null)
        {
            Array.Clear(RegExpBuiltin.LastCaptures);
            return;
        }
        if (result.Tag == JsValueTag.Object)
        {
            var resultHandle = result.AsObjectHandle();
            // Pin result as root before accessing its properties, preventing GC
            // from collecting it during property reads below.
            var rootMark = _heap.RootCount;
            _heap.PushRoot(resultHandle);
            try
            {
                var resultObj = _heap.GetObject(resultHandle);
                var resultVal = result;
                if (TryGetPropertyValue(resultObj, resultVal, "0", out var full))
                    RegExpBuiltin.LastCaptures[0] = ToStringValue(full);
                else
                    RegExpBuiltin.LastCaptures[0] = string.Empty;
                for (int i = 1; i <= 9; i++)
                {
                    if (TryGetPropertyValue(resultObj, resultVal, i.ToString(), out var cap))
                        RegExpBuiltin.LastCaptures[i] = cap.Tag == JsValueTag.Undefined ? string.Empty : ToStringValue(cap);
                    else
                        RegExpBuiltin.LastCaptures[i] = string.Empty;
                }
            }
            finally
            {
                _heap.PopRootsTo(rootMark);
            }
        }
    }

    // ECMA-262 22.2.5.2.1 step helper: AdvanceStringIndex.
    private static int AdvanceStringIndex(string S, int index, bool unicode)
    {
        if (!unicode || index + 1 >= S.Length)
            return index + 1;
        var first = S[index];
        if (first >= 0xD800 && first <= 0xDBFF)
        {
            var second = S[index + 1];
            if (second >= 0xDC00 && second <= 0xDFFF)
                return index + 2;
        }
        return index + 1;
    }

    private static double AdvanceStringIndexNumber(string S, double index, bool unicode)
    {
        if (index < 0)
        {
            index = 0;
        }

        if (index >= S.Length || index > int.MaxValue)
        {
            return index + 1;
        }

        return AdvanceStringIndex(S, (int)index, unicode);
    }

    // ECMA-262 7.3.18 SpeciesConstructor ( O, defaultConstructor ).
    private JsValue SpeciesConstructor(JsValue O, ObjectHandle defaultConstructorHandle)
    {
        // 1. Assert: Type(O) is Object.
        if (O.Tag != JsValueTag.Object)
            return JsValue.FromObject(defaultConstructorHandle);
        var obj = _heap.GetObject(O.AsObjectHandle());
        // 2. Let C be ? Get(O, "constructor").
        if (!TryGetPropertyValue(obj, O, "constructor", out var C))
            return JsValue.FromObject(defaultConstructorHandle);
        // 3. If C is undefined, return defaultConstructor.
        if (C.Tag == JsValueTag.Undefined)
            return JsValue.FromObject(defaultConstructorHandle);
        // 4. If Type(C) is not Object, throw a TypeError exception.
        if (C.Tag != JsValueTag.Object)
            throw new JsThrownException(CreateTypeError("SpeciesConstructor: 'constructor' is not an object."));
        var cObj = _heap.GetObject(C.AsObjectHandle());
        // 5. Let S be ? Get(C, @@species).
        var speciesSymbol = GetWellKnownSymbol("species");
        JsValue S = JsValue.Undefined;
        if (speciesSymbol.Tag == JsValueTag.Symbol &&
            cObj.TryGetOwnSymbolProperty(speciesSymbol.AsSymbolId(), out var speciesDesc))
        {
            if (speciesDesc.IsAccessor)
            {
                var getter = speciesDesc.Get;
                if (getter.Tag != JsValueTag.Undefined)
                    S = CallFunction(getter, Array.Empty<JsValue>(), C);
            }
            else
            {
                S = speciesDesc.Value;
            }
        }
        // 6. If S is either undefined or null, return defaultConstructor.
        if (S.Tag == JsValueTag.Undefined || S.Tag == JsValueTag.Null)
            return JsValue.FromObject(defaultConstructorHandle);
        // 7. If IsConstructor(S) is true, return S.
        if (S.Tag == JsValueTag.Object && IsConstructableTarget(S.AsObjectHandle()))
            return S;
        // 8. Throw a TypeError exception.
        throw new JsThrownException(CreateTypeError("SpeciesConstructor: @@species is not a constructor."));
    }

    // ECMA-262 7.2.8 IsRegExp ( argument ).
    private bool IsRegExp(JsValue argument)
    {
        // 1. If Type(argument) is not Object, return false.
        if (argument.Tag != JsValueTag.Object) return false;
        // 2. Let matcher be ? Get(argument, @@match).
        var obj = _heap.GetObject(argument.AsObjectHandle());
        var matchSymbol = GetWellKnownSymbol("match");
        JsValue matcher = JsValue.Undefined;
        if (matchSymbol.Tag == JsValueTag.Symbol &&
            obj.TryGetOwnSymbolProperty(matchSymbol.AsSymbolId(), out var matchDesc))
        {
            if (matchDesc.IsAccessor && matchDesc.Get.Tag != JsValueTag.Undefined)
                matcher = CallFunction(matchDesc.Get, Array.Empty<JsValue>(), argument);
            else
                matcher = matchDesc.Value;
        }
        // 3. If matcher is not undefined, return ToBoolean(matcher).
        if (matcher.Tag != JsValueTag.Undefined)
            return IsTruthy(matcher);
        // 4. If argument has a [[RegExpMatcher]] internal slot, return true.
        if (obj is RegExpObject) return true;
        // 5. Return false.
        return false;
    }

    // Proxy intercept helpers — ECMA-262 28.2 internal method dispatch.
    // Each method checks for a handler trap; when present the trap is called
    // with the proper arguments. When absent the operation falls through to
    // the target object.

    [MayExecuteJs]
    private JsValue? TryGetProxyTrap(ProxyObject proxy, string trapName)
    {
        if (proxy.IsRevoked)
            throw new JsThrownException(CreateTypeError(
                "Cannot perform '" + trapName + "' on a revoked proxy."));
        var handlerHandle = proxy.HandlerHandle!.Value;
        var handler = _heap.GetObject(handlerHandle);
        var handlerValue = JsValue.FromObject(handlerHandle);
        if (!TryGetPropertyValue(handler, handlerValue, trapName, out var trapValue))
        {
            return null;
        }

        if (trapValue.Tag is JsValueTag.Undefined or JsValueTag.Null)
        {
            return null;
        }

        if (!IsCallable(trapValue))
        {
            throw new JsThrownException(CreateTypeError("Proxy trap '" + trapName + "' is not callable."));
        }

        return trapValue;
    }

    private bool IsCallableTarget(ObjectHandle targetHandle)
        => IsCallableTarget(targetHandle, new HashSet<ObjectHandle>());

    private bool IsCallableTarget(ObjectHandle targetHandle, HashSet<ObjectHandle> visited)
    {
        if (!visited.Add(targetHandle))
        {
            return false;
        }

        var targetObj = _heap.GetObject(targetHandle);
        return targetObj switch
        {
            JsFunctionObject => true,
            NativeFunctionObject => true,
            BoundFunctionObject bound when bound.TargetFunction.Tag == JsValueTag.Object =>
                IsCallableTarget(bound.TargetFunction.AsObjectHandle(), visited),
            ProxyObject nestedProxy => IsCallableTarget(nestedProxy.TargetHandle, visited),
            _ => false
        };
    }

    private bool IsConstructableTarget(ObjectHandle targetHandle)
        => IsConstructableTarget(targetHandle, new HashSet<ObjectHandle>());

    private bool IsConstructableTarget(ObjectHandle targetHandle, HashSet<ObjectHandle> visited)
    {
        if (!visited.Add(targetHandle))
        {
            return false;
        }

        var targetObj = _heap.GetObject(targetHandle);
        return targetObj switch
        {
            JsFunctionObject jsFn => jsFn.Kind is not (FunctionKind.Generator or FunctionKind.AsyncGenerator),
            NativeFunctionObject nativeFn => nativeFn.IsConstructor,
            BoundFunctionObject bound when bound.TargetFunction.Tag == JsValueTag.Object =>
                IsConstructableTarget(bound.TargetFunction.AsObjectHandle(), visited),
            ProxyObject nestedProxy => IsConstructableTarget(nestedProxy.TargetHandle, visited),
            _ => false
        };
    }

    private bool IsTargetExtensible(ObjectHandle targetHandle)
    {
        var targetObj = _heap.GetObject(targetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return IsTargetExtensible(nestedProxy.TargetHandle);
        }

        return targetObj.Extensible;
    }

    private bool TryGetOwnPropertyDescriptorForTarget(ObjectHandle targetHandle, string prop, out JsPropertyDescriptor descriptor)
    {
        var targetObj = _heap.GetObject(targetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyTryGetOwnPropertyDescriptor(nestedProxy, prop, out descriptor);
        }

        return targetObj.TryGetOwnProperty(prop, out descriptor);
    }

    private bool DescriptorCompatibleWithTarget(bool targetExtensible, bool hasTargetDesc, JsPropertyDescriptor targetDesc, JsPropertyDescriptor resultDesc)
    {
        if (!hasTargetDesc)
        {
            if (!targetExtensible)
            {
                return false;
            }

            return resultDesc.Configurable;
        }

        // ECMA-262 10.5.5 [[GetOwnProperty]] step 22:
        // If resultDesc.[[Configurable]] is false, then
        //   a. If targetDesc is undefined or targetDesc.[[Configurable]] is true,
        //      throw a TypeError exception.
        if (!resultDesc.Configurable && targetDesc.Configurable)
        {
            return false;
        }

        if (!targetDesc.Configurable)
        {
            if (resultDesc.Configurable)
            {
                return false;
            }

            if (targetDesc.IsAccessor != resultDesc.IsAccessor)
            {
                return false;
            }

            if (!targetDesc.IsAccessor)
            {
                if (!targetDesc.Writable && resultDesc.Writable)
                {
                    return false;
                }

                if (!targetDesc.Writable && !AreStrictlyEqual(resultDesc.Value, targetDesc.Value))
                {
                    return false;
                }

                // ECMA-262 10.5.5 [[GetOwnProperty]] step 17.b:
                // If resultDesc has [[Writable]] field and resultDesc.[[Writable]] is false,
                // and targetDesc.[[Writable]] is true, throw TypeError.
                // (The HasWritable flag true on the result desc means [[Writable]] was specified
                // and is false; this is set during ToPropertyDescriptor parsing.)
                if (targetDesc.Writable && !resultDesc.Writable && resultDesc.HasWritable)
                {
                    return false;
                }
            }
            else
            {
                if (!AreStrictlyEqual(resultDesc.Get, targetDesc.Get) ||
                    !AreStrictlyEqual(resultDesc.Set, targetDesc.Set))
                {
                    return false;
                }
            }
        }

        if (!targetDesc.Configurable && resultDesc.Configurable)
        {
            return false;
        }

        if (!targetExtensible && !hasTargetDesc)
        {
            return false;
        }

        return true;
    }

    internal string TypeOfName(InterpreterFrame frame, int slot)
    {
        var name = SlotNameTable.GetName(frame.Function, slot);
        if (name is null)
        {
            return "undefined";
        }

        for (var env = (EnvironmentRecord?)frame.Environment; env is not null; env = env.OuterEnv)
        {
            if (!env.HasBinding(name))
            {
                continue;
            }

            var status = env.GetBindingValue(name, strict: frame.Function.IsStrictMode, out var envValue);
            if (status == BindingOpResult.Ok)
            {
                return TypeOfValue(envValue);
            }

            ThrowBindingFailure(frame, status, name, assignment: false);
            return "undefined";
        }

        return "undefined";
    }

    private bool ValueToBooleanProxy(JsValue value) => IsTruthy(value);

    [MayExecuteJs]
    private JsValue ProxyGet(ProxyObject proxy, JsValue receiver, string prop)
    {
        var trap = TryGetProxyTrap(proxy, "get");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var propVal = JsValue.FromString(prop);
            var trapResult = CallFunction(trap.Value, new[] { target, propVal, receiver },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
            if (TryGetOwnPropertyDescriptorForTarget(proxy.TargetHandle, prop, out var targetDesc) &&
                !targetDesc.Configurable)
            {
                if (!targetDesc.IsAccessor && !targetDesc.Writable &&
                    !AreStrictlyEqual(trapResult, targetDesc.Value))
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy get trap must return the target value for non-writable, non-configurable data properties."));
                }

                if (targetDesc.IsAccessor && targetDesc.Get.Tag == JsValueTag.Undefined &&
                    trapResult.Tag != JsValueTag.Undefined)
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy get trap must return undefined for non-configurable accessor properties without a getter."));
                }
            }

            return trapResult;
        }
        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyGet(nestedProxy, receiver, prop);
        }
        return TryGetPropertyValue(targetObj, receiver, prop, out var value)
            ? value : JsValue.Undefined;
    }

    [MayExecuteJs]
    private JsValue ProxyGetSymbol(ProxyObject proxy, JsValue receiver, long symbolId)
    {
        var trap = TryGetProxyTrap(proxy, "get");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var propVal = JsValue.SymbolFromId(symbolId);
            return CallFunction(trap.Value, new[] { target, propVal, receiver },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyGetSymbol(nestedProxy, receiver, symbolId);
        }

        return targetObj.TryGetSymbolProperty(symbolId, h => _heap.GetObject(h), out var desc)
            ? GetDescriptorValue(desc, receiver)
            : JsValue.Undefined;
    }

    [MayExecuteJs]
    private bool ProxySet(ProxyObject proxy, JsValue receiver, string prop, JsValue value)
    {
        var trap = TryGetProxyTrap(proxy, "set");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var propVal = JsValue.FromString(prop);
            var result = CallFunction(trap.Value,
                new[] { target, propVal, value, receiver },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
            if (!ValueToBooleanProxy(result))
            {
                return false;
            }

            // ECMA-262 10.5.9 [[Set]] invariant: a successful trap cannot contradict a
            // non-configurable own property on the target — a non-writable data property
            // must keep its value, and an accessor with no setter cannot be written.
            if (TryGetOwnPropertyDescriptorForTarget(proxy.TargetHandle, prop, out var targetDesc) &&
                !targetDesc.Configurable)
            {
                if (!targetDesc.IsAccessor && !targetDesc.Writable && !SameValue(value, targetDesc.Value))
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy set trap reported success for a non-configurable, non-writable own property with a different value."));
                }

                if (targetDesc.IsAccessor && targetDesc.Set.Tag is JsValueTag.Undefined)
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy set trap reported success for a non-configurable accessor own property with no setter."));
                }
            }

            return true;
        }
        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxySet(nestedProxy, receiver, prop, value);
        }
        // ECMA-262 10.5.9 Proxy [[Set]] step 7: no trap → target.[[Set]](P, V, Receiver).
        // The ordinary [[Set]] algorithm uses `receiver` when creating a new property
        // (step 5.f), so the proxy's defineProperty trap fires if applicable.
        return SetPropertyValue(proxy.TargetHandle, targetObj, prop, value, receiver);
    }

    [MayExecuteJs]
    private bool ProxyHas(ProxyObject proxy, string prop)
    {
        var trap = TryGetProxyTrap(proxy, "has");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var propVal = JsValue.FromString(prop);
            var result = CallFunction(trap.Value, new[] { target, propVal },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
            var trapResult = ValueToBooleanProxy(result);
            if (!trapResult &&
                TryGetOwnPropertyDescriptorForTarget(proxy.TargetHandle, prop, out var targetDesc) &&
                (!targetDesc.Configurable || !IsTargetExtensible(proxy.TargetHandle)))
            {
                throw new JsThrownException(CreateTypeError(
                    "Proxy has trap cannot report a non-configurable or non-extensible own property as absent."));
            }

            return trapResult;
        }
        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyHas(nestedProxy, prop);
        }
        return targetObj.TryGetProperty(prop, h => _heap.GetObject(h), out _);
    }

    [MayExecuteJs]
    private bool ProxyDelete(ProxyObject proxy, string prop)
    {
        var trap = TryGetProxyTrap(proxy, "deleteProperty");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var propVal = JsValue.FromString(prop);
            var result = CallFunction(trap.Value, new[] { target, propVal },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
            var trapResult = ValueToBooleanProxy(result);
            if (trapResult &&
                TryGetOwnPropertyDescriptorForTarget(proxy.TargetHandle, prop, out var targetDesc) &&
                !targetDesc.Configurable)
            {
                throw new JsThrownException(CreateTypeError(
                    "Proxy deleteProperty trap cannot report deletion of a non-configurable own property."));
            }

            if (trapResult &&
                TryGetOwnPropertyDescriptorForTarget(proxy.TargetHandle, prop, out _) &&
                !IsTargetExtensible(proxy.TargetHandle))
            {
                throw new JsThrownException(CreateTypeError(
                    "Proxy deleteProperty trap cannot report deletion of an existing property on a non-extensible target."));
            }

            return trapResult;
        }
        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyDelete(nestedProxy, prop);
        }
        if (targetObj.TryGetOwnProperty(prop, out _))
        {
            return targetObj.DeleteProperty(prop);
        }

        return true;
    }

    [MayExecuteJs]
    private JsValue ProxyCall(ProxyObject proxy, IReadOnlyList<JsValue> args, JsValue thisValue)
    {
        var trap = TryGetProxyTrap(proxy, "apply");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var argsArray = CreateArrayFromElements(args);
            var argsHandle = _heap.AllocateObject(argsArray, AllocationSite.Current());
            return CallFunction(trap.Value,
                new[] { target, thisValue, JsValue.FromObject(argsHandle) },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
        }
        return CallFunction(JsValue.FromObject(proxy.TargetHandle), args, thisValue);
    }

    [MayExecuteJs]
    private JsValue ProxyConstruct(ProxyObject proxy, IReadOnlyList<JsValue> args, JsValue newTarget)
    {
        var trap = TryGetProxyTrap(proxy, "construct");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var argsArray = CreateArrayFromElements(args);
            var argsHandle = _heap.AllocateObject(argsArray, AllocationSite.Current());
            var result = CallFunction(trap.Value,
                new[] { target, JsValue.FromObject(argsHandle), newTarget },
                JsValue.FromObject(proxy.HandlerHandle!.Value));
            if (result.Tag != JsValueTag.Object)
            {
                throw new JsThrownException(CreateTypeError("Proxy construct trap must return an object."));
            }

            return result;
        }
        return ConstructFunction(JsValue.FromObject(proxy.TargetHandle), args, newTarget);
    }

    [MayExecuteJs]
    private JsValue ProxyGetPrototypeOf(ProxyObject proxy)
    {
        var trap = TryGetProxyTrap(proxy, "getPrototypeOf");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var result = CallFunction(trap.Value, new[] { target }, JsValue.FromObject(proxy.HandlerHandle!.Value));
            if (result.Tag != JsValueTag.Object && result.Tag != JsValueTag.Null)
            {
                throw new JsThrownException(CreateTypeError("Proxy getPrototypeOf trap must return object or null."));
            }

            if (!IsTargetExtensible(proxy.TargetHandle))
            {
                var targetObject = _heap.GetObject(proxy.TargetHandle);
                var targetProto = targetObject.PrototypeHandle is { } protoHandle
                    ? JsValue.FromObject(protoHandle)
                    : JsValue.Null;
                if (!AreStrictlyEqual(result, targetProto))
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy getPrototypeOf trap must return the same prototype for non-extensible targets."));
                }
            }

            return result;
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyGetPrototypeOf(nestedProxy);
        }
        return targetObj.PrototypeHandle is { } proto ? JsValue.FromObject(proto) : JsValue.Null;
    }

    [MayExecuteJs]
    private bool ProxySetPrototypeOf(ProxyObject proxy, JsValue protoValue)
    {
        var trap = TryGetProxyTrap(proxy, "setPrototypeOf");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var result = CallFunction(trap.Value, new[] { target, protoValue }, JsValue.FromObject(proxy.HandlerHandle!.Value));
            var trapResult = ValueToBooleanProxy(result);
            // ECMA-262 28.2.2.13 [[SetPrototypeOf]] step 9: if trap result is false, return false.
            if (!trapResult)
                return false;
            // Step 10: extensibleTarget = IsExtensible(target) — must be called.
            var extensibleTarget = IsTargetExtensible(proxy.TargetHandle);
            // Step 11: if extensibleTarget is true, return true.
            if (extensibleTarget)
                return true;
            // Step 12: targetProto = target.[[GetPrototypeOf]]()
            var spTargetObj = _heap.GetObject(proxy.TargetHandle);
            if (spTargetObj is ProxyObject spNestedProxy)
            {
                var targetProto = ProxyGetPrototypeOf(spNestedProxy);
                // Step 13: if SameValue(V, targetProto) is false, throw TypeError.
                if (!AreStrictlyEqual(protoValue, targetProto))
                    throw new JsThrownException(CreateTypeError(
                        "Proxy setPrototypeOf trap cannot change prototype of a non-extensible target."));
            }
            else
            {
                var targetProto = spTargetObj.PrototypeHandle is { } proto ? JsValue.FromObject(proto) : JsValue.Null;
                if (!AreStrictlyEqual(protoValue, targetProto))
                    throw new JsThrownException(CreateTypeError(
                        "Proxy setPrototypeOf trap cannot change prototype of a non-extensible target."));
            }
            return true;
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxySetPrototypeOf(nestedProxy, protoValue);
        }
        if (protoValue.Tag == JsValueTag.Object)
        {
            targetObj.SetPrototype(protoValue.AsObjectHandle());
            _heap.WriteBarrier(proxy.TargetHandle, protoValue.AsObjectHandle());
            return true;
        }

        if (protoValue.Tag == JsValueTag.Null)
        {
            targetObj.SetPrototype(null);
            return true;
        }

        return false;
    }

    [MayExecuteJs]
    private bool ProxyIsExtensible(ProxyObject proxy)
    {
        var trap = TryGetProxyTrap(proxy, "isExtensible");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var result = CallFunction(trap.Value, new[] { target }, JsValue.FromObject(proxy.HandlerHandle!.Value));
            var trapResult = ValueToBooleanProxy(result);
            var targetExtensible = IsTargetExtensible(proxy.TargetHandle);
            if (trapResult != targetExtensible)
            {
                throw new JsThrownException(CreateTypeError(
                    "Proxy isExtensible trap result must match the target extensibility."));
            }

            return trapResult;
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyIsExtensible(nestedProxy);
        }

        return targetObj.Extensible;
    }

    [MayExecuteJs]
    private bool ProxyPreventExtensions(ProxyObject proxy)
    {
        var trap = TryGetProxyTrap(proxy, "preventExtensions");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var result = CallFunction(trap.Value, new[] { target }, JsValue.FromObject(proxy.HandlerHandle!.Value));
            var trapResult = ValueToBooleanProxy(result);
            // ECMA-262 28.2.2.15 [[PreventExtensions]] step 10.c:
            // If trap result is true but target is still extensible, throw TypeError.
            if (trapResult && IsTargetExtensible(proxy.TargetHandle))
                throw new JsThrownException(CreateTypeError(
                    "Proxy preventExtensions trap reported success but target is extensible."));
            return trapResult;
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
        {
            return ProxyPreventExtensions(nestedProxy);
        }

        targetObj.PreventExtensions();
        return true;
    }

    [MayExecuteJs]
    private List<JsValue> ProxyOwnKeys(ProxyObject proxy)
    {
        var trap = TryGetProxyTrap(proxy, "ownKeys");
        if (trap is not null)
        {
            var target = JsValue.FromObject(proxy.TargetHandle);
            var result = CallFunction(trap.Value, new[] { target }, JsValue.FromObject(proxy.HandlerHandle!.Value));
            if (result.Tag != JsValueTag.Object)
            {
                throw new JsThrownException(CreateTypeError("Proxy ownKeys trap must return an object."));
            }

            var listObj = _heap.GetObject(result.AsObjectHandle());
            var len = GetArrayLength(listObj);
            var keys = new List<JsValue>(len);
            for (var i = 0; i < len; i++)
            {
                var key = i.ToString(System.Globalization.CultureInfo.InvariantCulture);
                if (!TryGetPropertyValue(listObj, result, key, out var item))
                {
                    continue;
                }

                if (item.Tag == JsValueTag.String || item.Tag == JsValueTag.Symbol)
                {
                    keys.Add(item);
                }
                else
                {
                    // ECMA-262 28.2.2.11 step 8: CreateListFromArrayLike
                    // with elementTypes « String, Symbol » — throw TypeError
                    // for entries of any other type.
                    throw new JsThrownException(CreateTypeError(
                        "Proxy ownKeys trap returned an entry whose type is not String or Symbol."));
                }
            }

            // ECMA-262 28.2.2.11 [[OwnPropertyKeys]] invariant checks.
            // 1. No duplicate entries.
            var seen = new HashSet<string>();
            foreach (var k in keys)
            {
                var strKey = k.Tag == JsValueTag.Symbol ? $"@@{k.AsSymbolId()}" : k.AsString();
                if (!seen.Add(strKey))
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy ownKeys trap returned duplicate entries."));
                }
            }

            // 2. Non-extensible target: all own property keys must be present,
            // and the result must not contain extra keys not in the target.
            if (!IsTargetExtensible(proxy.TargetHandle))
            {
                var targetObjForKeys = _heap.GetObject(proxy.TargetHandle);
                var targetKeySet = new HashSet<string>();
                foreach (var ownProp in targetObjForKeys.EnumerateOwnProperties())
                {
                    targetKeySet.Add(ownProp.Key);
                    if (!seen.Contains(ownProp.Key))
                    {
                        throw new JsThrownException(CreateTypeError(
                            "Proxy ownKeys trap must include all own property keys for a non-extensible target."));
                    }
                }
                foreach (var ownSym in targetObjForKeys.EnumerateOwnSymbolProperties())
                {
                    var symKey = $"@@{ownSym.Key}";
                    targetKeySet.Add(symKey);
                    if (!seen.Contains(symKey))
                    {
                        throw new JsThrownException(CreateTypeError(
                            "Proxy ownKeys trap must include all own symbol keys for a non-extensible target."));
                    }
                }
                // ECMA-262 28.2.2.11 step 20: any key in the trap result that is
                // not an own property of the target must be rejected for a
                // non-extensible target.
                foreach (var k in seen)
                {
                    if (!targetKeySet.Contains(k))
                    {
                        throw new JsThrownException(CreateTypeError(
                            "Proxy ownKeys trap returned a key not present on a non-extensible target."));
                    }
                }
            }

            // 3. Non-configurable own properties must be in the result.
            foreach (var ownProp in _heap.GetObject(proxy.TargetHandle).EnumerateOwnProperties())
            {
                if (!ownProp.Value.Configurable && !seen.Contains(ownProp.Key))
                {
                    throw new JsThrownException(CreateTypeError(
                        "Proxy ownKeys trap must report a non-configurable own property."));
                }
            }

            return keys;
        }

        var targetObj = _heap.GetObject(proxy.TargetHandle);
        if (targetObj is ProxyObject nestedProxy)
