                foreach (var k in keys)
                {
                    var newValue = InternalizeJsonProperty(valueHandle, k, reviver);
                    if (newValue.Tag == JsValueTag.Undefined)
                    {
                        if (valueObj is ProxyObject proxyDelete)
                        {
