        if (px.Tag == JsValueTag.BigInt && py.Tag == JsValueTag.BigInt)
            return px.AsBigInt() <= py.AsBigInt();

        if (px.Tag == JsValueTag.BigInt && py.Tag is JsValueTag.Int32 or JsValueTag.Number)
        {
            var number = ToNumber(py);
