            return string.CompareOrdinal(px.AsString(), py.AsString()) >= 0;

        if (px.Tag == JsValueTag.BigInt && py.Tag == JsValueTag.Boolean)
            return px.AsBigInt() >= (py.AsBoolean() ? BigInteger.One : BigInteger.Zero);
        if (py.Tag == JsValueTag.BigInt && px.Tag == JsValueTag.Boolean)
            return (px.AsBoolean() ? BigInteger.One : BigInteger.Zero) >= py.AsBigInt();

        if (px.Tag == JsValueTag.BigInt && py.Tag == JsValueTag.String)
        {
            if (Builtins.BigIntBuiltin.TryParseStringToBigInt(py.AsString(), out var ny))
                return px.AsBigInt() >= ny;
            return false;
        }

        if (px.Tag == JsValueTag.String && py.Tag == JsValueTag.BigInt)
        {
            if (Builtins.BigIntBuiltin.TryParseStringToBigInt(px.AsString(), out var nx))
                return nx >= py.AsBigInt();
            return false;
        }

        if (px.Tag == JsValueTag.BigInt && py.Tag == JsValueTag.BigInt)
            return px.AsBigInt() >= py.AsBigInt();

        if (px.Tag == JsValueTag.BigInt && py.Tag is JsValueTag.Int32 or JsValueTag.Number)
        {
            var number = ToNumber(py);
            return !double.IsNaN(number) && CompareBigIntAndDouble(px.AsBigInt(), number) >= 0;
        }

        if (py.Tag == JsValueTag.BigInt && px.Tag is JsValueTag.Int32 or JsValueTag.Number)
        {
            var number = ToNumber(px);
            return !double.IsNaN(number) && CompareBigIntAndDouble(py.AsBigInt(), number) <= 0;
        }

        return ToNumber(px) >= ToNumber(py);
    }

    private static int CompareBigIntAndDouble(System.Numerics.BigInteger left, double right)
    {
        if (double.IsPositiveInfinity(right))
        {
            return -1;
        }

        if (double.IsNegativeInfinity(right))
        {
            return 1;
        }

        var truncated = Math.Truncate(right);
        var cmp = left.CompareTo(new System.Numerics.BigInteger(truncated));
        if (cmp != 0 || truncated == right)
        {
            return cmp;
        }

        return right > 0 ? -1 : 1;
    }

    private bool TryInstanceOf(InterpreterFrame frame, JsValue left, JsValue right, out bool result)
    {
        result = false;

        if (right.Tag != JsValueTag.Object && right.Tag != JsValueTag.HostObject)
        {
            ThrowTypeError(frame, "Right-hand side of 'instanceof' must be an object.");
            return false;
        }

        var hasInstanceSymbolId = GetWellKnownSymbolId("hasInstance");
        if (hasInstanceSymbolId != 0)
        {
            var hasInstance = GetReceiverSymbolProperty(right, hasInstanceSymbolId);
            if (hasInstance.Tag != JsValueTag.Undefined)
            {
                if (!IsCallable(hasInstance))
                {
                    ThrowTypeError(frame, "@@hasInstance is not callable.");
                    return false;
                }

                try
                {
                    var methodResult = CallFunction(hasInstance, new[] { left }, right);
                    result = IsTruthy(methodResult);
                    return true;
                }
                catch (JsThrownException ex)
                {
                    if (frame.CatchHandlers.Count == 0)
                    {
                        throw;
                    }

                    ThrowOrHandle(frame, ex.Value);
                    return false;
                }
            }
        }

        if (!IsCallable(right))
        {
            ThrowTypeError(frame, "Right-hand side of 'instanceof' is not callable.");
            return false;
        }

        if (left.Tag != JsValueTag.Object && left.Tag != JsValueTag.HostObject)
        {
            result = false;
            return true;
        }

        var prototypeValue = GetReceiverProperty(right, "prototype");
        if (prototypeValue.Tag != JsValueTag.Object)
        {
            ThrowTypeError(frame, "Function has non-object prototype in 'instanceof'.");
            return false;
        }

        var targetPrototype = prototypeValue.AsObjectHandle();
        // Pin the prototype handle across the prototype-chain walk. The walk
        // triggers property resolution on each prototype object, which can
        // allocate (e.g. boxing the "constructor" property) and trigger a
        // MinorCollect that would invalidate unrooted handles.
        PinIfObject(prototypeValue);
        try
        {
            result = OrdinaryHasInstancePrototype(left, targetPrototype);
            return true;
        }
        catch (JsThrownException ex)
        {
            if (frame.CatchHandlers.Count == 0)
            {
                throw;
            }

            ThrowOrHandle(frame, ex.Value);
            return false;
        }
    }

    [MayExecuteJs]
    private bool OrdinaryHasInstancePrototype(JsValue value, ObjectHandle targetPrototype)
    {
        while (true)
        {
            JsValue nextProtoValue = value.Tag switch
            {
                JsValueTag.HostObject => GetHostObjectPrototype(value.AsHostObjectHandle()),
                JsValueTag.Object => ResolveObject(value) is ProxyObject proxyCurrent
                    ? ProxyGetPrototypeOf(proxyCurrent)
                    : ResolveObject(value).PrototypeHandle is { } protoHandle
                        ? JsValue.FromObject(protoHandle)
                        : JsValue.Null,
                _ => JsValue.Null
            };

            if (nextProtoValue.Tag == JsValueTag.Null)
            {
                return false;
            }

            if (nextProtoValue.Tag != JsValueTag.Object)
            {
                throw new JsThrownException(CreateTypeError("Object prototype is not an object or null."));
            }

            var proto = nextProtoValue.AsObjectHandle();
            if (proto.Equals(targetPrototype))
            {
                return true;
            }

            value = JsValue.FromObject(proto);
        }
    }

    private string TypeOfValue(JsValue value)
    {
        if (IsHtmlDda(value))
        {
            return "undefined";
        }

        if (value.Tag == JsValueTag.Object)
        {
            if (IsCallable(value))
            {
                return "function";
            }

            return "object";
        }

        return value.Tag switch
        {
            JsValueTag.Undefined => "undefined",
            JsValueTag.Null => "object",
            JsValueTag.Boolean => "boolean",
            JsValueTag.Int32 => "number",
            JsValueTag.Number => "number",
            JsValueTag.String => "string",
            JsValueTag.Symbol => "symbol",
            JsValueTag.BigInt => "bigint",
            JsValueTag.HostObject => "object",
            _ => "undefined"
        };
    }

    private bool IsHtmlDda(JsValue value)
        => value.Tag == JsValueTag.Object &&
           _heap.GetObject(value.AsObjectHandle()).IsHtmlDda;

    private enum PrimitiveHint
    {
        Default,
        String,
        Number
    }


